import {
    t
} from '../util/locale';
import {
    osmEntity,
    osmNote
} from '../osm';
import {
    svgIcon
} from '../svg/icon';


export function uiViewOnOSM(context) {
    var _what; // an osmEntity or osmNote


    function viewOnOSM(selection) {
        var url, type, id;
        if (_what instanceof osmEntity) {
            url = context.connection().entityURL(_what);
            type = context.connection().entityType(_what);
            id = context.connection().entityID(_what);
        } else if (_what instanceof osmNote) {
            url = context.connection().noteURL(_what);
            type = null;
            id = null;
        }

        var data = ((!_what || _what.isNew()) ? [] : [_what]);
        var link = selection.selectAll('.view-on-osm')
            .data(data, function (d) {
                return d.id;
            });

        // exit
        link.exit()
            .remove();

        // enter
        var linkEnter = link.enter()
            .append('a')
            .attr('class', 'view-on-osm')
            .attr('target', '_blank')
            .attr('href', url)
            .call(svgIcon('#iD-icon-out-link', 'inline'));

        linkEnter
            .append('span')
            .text(t('inspector.view_on_osm'));



        if (id && type) {

            if (type === 'node') {
                var linkEnter = link.enter()
                    .append('a')
                    .attr('class', 'view-on-osm')
                    .attr('target', '_blank')
                    .attr('href', `https://www.google.com/maps/@?api=1&viewpoint=${_what.loc[1]}%2C${_what.loc[0]}&map_action=pano`)
                    .call(svgIcon('#iD-icon-out-link', 'inline'));

                linkEnter
                    .append('span')
                    .text('View in streetview');
            }


            var typeAndId = link.enter()
                .append('p')
                .text(type + '/' + id)
                .append('p')
                .text(id);

            if (type === 'node') {
                typeAndId
                    .append('p')
                    .text(_what.loc[1] + ',' + _what.loc[0])
                    .append('p')
                    .text('[' + _what.loc[0] + ',' + _what.loc[1] + ']')
                    .append('p')
                    .text(id + ',' + _what.loc[1] + ',' + _what.loc[0]);
            }
        }
    }


    viewOnOSM.what = function (_) {
        if (!arguments.length) return _what;
        _what = _;
        return viewOnOSM;
    };

    return viewOnOSM;
}
